#include <assert.h>
#include <config.h>
#include <stdlib.h>
#include <unistd.h>
#include ELFUTILS_HEADER(dwfl)

static const Dwfl_Callbacks core_callbacks = {
        .find_elf = dwfl_build_id_find_elf,
        .find_debuginfo = dwfl_standard_find_debuginfo,
};

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
        char name[] = "/tmp/fuzz-dwfl-core.XXXXXX";
        int fd = -1;
        ssize_t n;
        off_t offset;
        Elf *core = NULL;
        Dwfl *dwfl = NULL;

        fd = mkstemp(name);
        assert(fd >= 0);

        n = write(fd, data, size);
        assert(n == size);

        offset = lseek(fd, 0, SEEK_SET);
        assert(offset == 0);

        elf_version(EV_CURRENT);
        core = elf_begin(fd, ELF_C_READ_MMAP, NULL);
        if (core == NULL)
                goto cleanup;
        dwfl = dwfl_begin(&core_callbacks);
        assert(dwfl != NULL);
        if (dwfl_core_file_report(dwfl, core, NULL) < 0)
                goto cleanup;
        if (dwfl_report_end(dwfl, NULL, NULL) != 0)
                goto cleanup;

cleanup:
        dwfl_end(dwfl);
        elf_end(core);
        close(fd);
        unlink(name);
        return 0;
}

---BUILD---

set -eux
SANITIZER=${SANITIZER:-address}
flags="-O1 -fno-omit-frame-pointer -gline-tables-only -DFUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION -fsanitize=$SANITIZER -fsanitize=fuzzer-no-link"
export CC=${CC:-clang}
export CFLAGS=${CFLAGS:-$flags}
export CXX=${CXX:-clang++}
export CXXFLAGS=${CXXFLAGS:-$flags}
export SRC=${SRC:-$(realpath -- $(dirname -- "$0"))}
export OUT=${OUT:-"$SRC/out"}
mkdir -p "$OUT"
export LIB_FUZZING_ENGINE=${LIB_FUZZING_ENGINE:--fsanitize=fuzzer}
cd "$SRC/elfutils"
find -name Makefile.am | xargs sed -i 's/,--no-undefined//'
sed -i 's/^\(ZDEFS_LDFLAGS=\).*/\1/' configure.ac
autoreconf -i -f
if ! ./configure --enable-maintainer-mode --disable-debuginfod --disable-libdebuginfod             --without-bzlib --without-lzma --without-zstd            CC="$CC" CFLAGS="-Wno-error $CFLAGS" CXX="-Wno-error $CXX" CXXFLAGS="$CXXFLAGS" LDFLAGS="$CFLAGS"; then
    cat config.log
    exit 1
fi
ASAN_OPTIONS=detect_leaks=0 make -j$(nproc) V=1
$CC $CFLAGS     -D_GNU_SOURCE -DHAVE_CONFIG_H   -I. -I./lib -I./libelf -I./libebl -I./libdw -I./libdwelf -I./libdwfl -I./libasm         -c "$SRC/fuzz-dwfl-core.c" -o fuzz-dwfl-core.o
$CXX $CXXFLAGS $LIB_FUZZING_ENGINE fuzz-dwfl-core.o     ./libdw/libdw.a ./libelf/libelf.a -l:libz.a     -o "$OUT/fuzz-dwfl-core"
cp "$SRC/fuzz-dwfl-core_seed_corpus.zip" "$OUT"
